MP="py -3.13 <your-picture-maker>/make-picture.py"
STY="Simple whiteboard marker line drawing in black and white: black marker outlines only on a pure white background, monochrome, all areas left white, one clean uniform thick black outline weight, friendly simple doodle, very few details, no texture marks, no crumb dots, no shading, no hatching, no text, the object centred with a wide white margin around it, no frame."
NEG="colour, colored, coloured fill, brown, tan, orange, yellow, green, red, lettuce, tomato, cheese, ham, shading, hatching, cross-hatching, stippling, dots, texture lines, grey tones, gradient, photo, realistic, 3d render, text, letters, words, numbers, watermark, logo, signature, blurry, low quality, sketchy messy lines, thin lines, frame, border, paper edge"
O=assets_work/wb
$MP "$STY Subject: one slice of sandwich bread seen from above at a slight angle, its top covered by a layer of peanut butter drawn as a wavy outlined area just inside the crust, a butter knife lying across it spreading the peanut butter, only three curved swoosh lines on the spread." $O/spread_c --n 4 --seed 321 --negative "$NEG"
$MP "$STY Subject: a whole peanut butter sandwich, two slices of bread stacked on top of each other, seen at a slight three-quarter angle from above, between the slices one smooth even thin band of filling shows along the edge, no vegetables." $O/stack_c --n 4 --seed 421 --negative "$NEG"
$MP "$STY Subject: a whole square sandwich lying on a rectangular cutting board seen from above at a slight angle, a big kitchen knife cutting down through the sandwich along its diagonal from one corner to the opposite corner, the blade half sunk into the sandwich." $O/cut_c --n 4 --seed 521 --negative "$NEG"
$MP "$STY Subject: two triangle sandwich halves on a round plate, slightly apart from each other, on each cut edge one smooth even band of filling shows between the two bread layers, no vegetables." $O/halves_c --n 4 --seed 621 --negative "$NEG"
